import PricingSectionV4 from "./components/pricing-section-v4"

export default function Page() {
  return <PricingSectionV4 />
}

"use client"

import { useState } from "react"
import { CheckIcon } from "lucide-react"

import { Button } from "@/components/ui/button"
import {
  Card,
  CardContent,
  CardDescription,
  CardFooter,
  CardHeader,
  CardTitle,
} from "@/components/ui/card"
import {
  Select,
  SelectContent,
  SelectGroup,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select"
import { cn } from "@/lib/utils"
import type { PricingPlan } from "../lib/pricing-plans"
import ProFluidShell from "./pro-fluid-shell"

type PricingCardProps = {
  plan: PricingPlan
}

export default function PricingCard({ plan }: PricingCardProps) {
  const defaultCreditId = plan.creditOptions?.[0]?.id
  const [creditId, setCreditId] = useState(defaultCreditId ?? "")

  const selectedOption = plan.creditOptions?.find(
    (option) => option.id === creditId
  )
  const price = selectedOption?.price ?? plan.price ?? ""
  const isPro = plan.id === "pro"

  return (
    <li className="flex min-w-0 flex-col">
      {isPro ? (
        <ProFluidShell>
          {(fluidActive) => (
            <PlanCard
              plan={plan}
              price={price}
              creditId={creditId}
              onCreditChange={setCreditId}
              transparent
              onFluid={fluidActive}
            />
          )}
        </ProFluidShell>
      ) : (
        <PlanCard
          plan={plan}
          price={price}
          creditId={creditId}
          onCreditChange={setCreditId}
        />
      )}

      <div className="flex flex-col gap-3 px-1 pt-6">
        <p className="min-h-5 text-sm leading-5 text-muted-foreground">
          {plan.featuresIntro}
        </p>
        <ul className="flex flex-col">
          {plan.features.map((feature) => (
            <li
              key={feature}
              className="flex min-h-11 items-start gap-2.5 border-b border-dashed border-border py-3 text-sm leading-relaxed text-foreground last:border-b-0"
            >
              <CheckIcon
                aria-hidden
                className="mt-0.5 size-4 shrink-0 text-muted-foreground"
              />
              <span>{feature}</span>
            </li>
          ))}
        </ul>
      </div>
    </li>
  )
}

type PlanCardProps = {
  plan: PricingPlan
  price: string
  creditId: string
  onCreditChange: (value: string) => void
  transparent?: boolean
  /** Fluid is painting — use light-on-dark copy over the dark solver. */
  onFluid?: boolean
}

function PlanCard({
  plan,
  price,
  creditId,
  onCreditChange,
  transparent = false,
  onFluid = false,
}: PlanCardProps) {
  return (
    <Card
      className={cn(
        "flex min-h-72 flex-1 flex-col gap-0 rounded-2xl py-0 shadow-none ring-0",
        transparent ? "bg-transparent" : "bg-muted"
      )}
    >
      <CardHeader className="gap-1 px-6 pt-6 pb-0">
        <CardTitle
          className={cn(
            "text-2xl font-semibold tracking-tight",
            onFluid ? "text-white" : "text-foreground"
          )}
        >
          {plan.name}
        </CardTitle>
        <CardDescription
          className={cn(
            "text-sm",
            onFluid ? "text-white/70" : "text-muted-foreground"
          )}
        >
          {plan.description}
        </CardDescription>
      </CardHeader>

      <CardContent className="mt-auto flex flex-col gap-4 px-6 pt-10 pb-0">
        <p className="flex items-baseline gap-2">
          <span
            className={cn(
              "text-4xl font-semibold tracking-tight",
              onFluid ? "text-white" : "text-foreground"
            )}
          >
            {price}
          </span>
          <span
            className={cn(
              "text-sm",
              onFluid ? "text-white/65" : "text-muted-foreground"
            )}
          >
            {plan.priceSuffix}
          </span>
        </p>

        <CreditControl
          label={plan.creditLabel}
          options={plan.creditOptions}
          creditId={creditId}
          onCreditChange={onCreditChange}
          onFluid={onFluid}
        />
      </CardContent>

      <CardFooter className="border-t-0 bg-transparent p-6 pt-4">
        <Button
          className={cn(
            "w-full rounded-full",
            onFluid && "bg-white text-black hover:bg-white/90"
          )}
          size="lg"
        >
          {plan.ctaLabel}
        </Button>
      </CardFooter>
    </Card>
  )
}

/** Shared chrome for static credit pills and the Pro Select — matches Button lg. */
const creditControlClassName = (onFluid: boolean) =>
  cn(
    "flex !h-9 w-full shrink-0 items-center rounded-full border-0 px-4 text-sm shadow-none",
    onFluid
      ? "!bg-white/15 text-white hover:!bg-white/20"
      : "!bg-background text-foreground hover:!bg-background"
  )

type CreditControlProps = {
  label?: string
  options?: PricingPlan["creditOptions"]
  creditId: string
  onCreditChange: (value: string) => void
  onFluid: boolean
}

function CreditControl({
  label,
  options,
  creditId,
  onCreditChange,
  onFluid,
}: CreditControlProps) {
  if (options) {
    return (
      <Select value={creditId} onValueChange={onCreditChange}>
        <SelectTrigger
          aria-label="Pro credit amount"
          className={cn(
            creditControlClassName(onFluid),
            "justify-between",
            onFluid && "[&_svg]:text-white/70"
          )}
        >
          <SelectValue />
        </SelectTrigger>
        <SelectContent>
          <SelectGroup>
            {options.map((option) => (
              <SelectItem key={option.id} value={option.id}>
                {option.label}
              </SelectItem>
            ))}
          </SelectGroup>
        </SelectContent>
      </Select>
    )
  }

  return (
    <div className={cn(creditControlClassName(onFluid), "justify-center")}>
      {label}
    </div>
  )
}

"use client"

import { useEffect, useRef, useState, type ReactNode } from "react"

import { createRenderer } from "./fluid/renderer"

type ProFluidShellProps = {
  children: (active: boolean) => ReactNode
  className?: string
}

/**
 * Self-contained WebGPU fluid card surface — same footprint as Free/Basic,
 * fluid fills the rounded rectangle with no muted overlay. Falls back to a
 * plain muted card when reduced-motion is set or init fails.
 */
export default function ProFluidShell({
  children,
  className,
}: ProFluidShellProps) {
  const rootRef = useRef<HTMLDivElement>(null)
  const canvasRef = useRef<HTMLCanvasElement>(null)
  const [active, setActive] = useState(false)

  useEffect(() => {
    const root = rootRef.current
    const canvas = canvasRef.current
    if (!root || !canvas) return

    const reduceMotion = window.matchMedia(
      "(prefers-reduced-motion: reduce)"
    ).matches
    if (reduceMotion) return

    const renderer = createRenderer({ canvas, inputTarget: root })
    void renderer.ready
      .then(() => {
        setActive(true)
      })
      .catch((error: unknown) => {
        console.error("[pricing-section-v4] fluid renderer failed", error)
        setActive(false)
      })

    return () => {
      renderer.dispose()
      setActive(false)
    }
  }, [])

  return (
    <div
      ref={rootRef}
      data-fluid-active={active ? "" : undefined}
      className={[
        "relative flex min-h-72 flex-1 flex-col overflow-hidden rounded-2xl",
        active ? "bg-black" : "bg-muted",
        className,
      ]
        .filter(Boolean)
        .join(" ")}
    >
      <canvas
        ref={canvasRef}
        aria-hidden
        className={[
          "pointer-events-none absolute inset-0 size-full touch-none transition-opacity duration-500",
          active ? "opacity-100" : "opacity-0",
        ].join(" ")}
      />
      <div className="relative z-10 flex min-h-72 flex-1 flex-col">
        {children(active)}
      </div>
    </div>
  )
}

import { surface, type Gpu, type Surface } from "vgpu"

import { installStirInput } from "./pointer-input"
import {
  createFluid,
  prepareFluid,
  renderFluid,
  resizeFluid,
  stepFluid,
  type Fluid,
} from "./simulation"

const FIXED_STEP = 1 / 60

interface RendererOptions {
  canvas: HTMLCanvasElement
  inputTarget: HTMLElement
}

function fixedStepCount(accumulator: number, elapsed: number) {
  let next = accumulator + Math.min(elapsed, 1 / 30)
  let steps = 0
  while (next >= FIXED_STEP && steps < 2) {
    next -= FIXED_STEP
    steps++
  }
  return { steps, accumulator: steps === 2 ? 0 : next }
}

export function createRenderer(options: RendererOptions) {
  let disposed = false
  let gpu: Gpu | undefined
  let canvasSurface: Surface | undefined
  let fluid: Fluid | undefined
  let input: ReturnType<typeof installStirInput> | undefined
  let animationFrame = 0
  let accumulator = 0
  let previous = 0
  let intersecting = true
  let intersection: IntersectionObserver | undefined

  const shouldStep = () =>
    !document.hidden && intersecting && Boolean(fluid && input && canvasSurface)

  const tick = (now: number) => {
    if (disposed) return
    if (shouldStep() && fluid && input && canvasSurface) {
      const fixed = fixedStepCount(accumulator, (now - previous) / 1000)
      accumulator = fixed.accumulator
      for (let i = 0; i < fixed.steps; i++) {
        stepFluid(fluid, input)
      }
      renderFluid(fluid, canvasSurface)
    }
    // Always reset the clock while paused so visibility changes never catch up.
    previous = now
    animationFrame = requestAnimationFrame(tick)
  }

  function dispose() {
    if (disposed) return
    disposed = true
    if (animationFrame) cancelAnimationFrame(animationFrame)
    intersection?.disconnect()
    input?.dispose()
    gpu?.dispose()
  }

  function fail(error: unknown): never {
    dispose()
    throw error
  }

  const initialize = async () => {
    const { init } = await import("vgpu")
    if (disposed) return
    const nextGpu = await init()
    if (disposed) {
      nextGpu.dispose()
      return
    }
    gpu = nextGpu
    canvasSurface = surface(gpu, options.canvas, { dpr: [1, 2] })
    fluid = createFluid(gpu)
    input = installStirInput(options.inputTarget)
    await prepareFluid(fluid, canvasSurface)
    if (disposed) return

    if (typeof IntersectionObserver !== "undefined") {
      intersection = new IntersectionObserver(
        (entries) => {
          intersecting = entries.some((entry) => entry.isIntersecting)
        },
        { threshold: 0.05 }
      )
      intersection.observe(options.inputTarget)
    }

    canvasSurface.onResize(() => {
      if (disposed || !fluid || !canvasSurface) return
      try {
        resizeFluid(fluid, canvasSurface)
      } catch (error) {
        fail(error)
      }
    })
    previous = performance.now()
    animationFrame = requestAnimationFrame(tick)
  }

  const ready = initialize().catch((error: unknown) => {
    if (disposed) return
    fail(error)
  })

  return { ready, dispose }
}

export interface StirInput {
  active: boolean
  from: [number, number]
  to: [number, number]
  velocity: [number, number]
  consumeStep(): void
  dispose(): void
}

/**
 * Stir input bound to the card wrapper (not the canvas), so Select/Button
 * keep normal clicks. Pointer splat only follows real movement over the card —
 * no synthetic idle squirts.
 */
export function installStirInput(target: HTMLElement): StirInput {
  let hovering = false
  let from: [number, number] = [0.5, 0.5]
  let to: [number, number] = [0.5, 0.5]
  let velocity: [number, number] = [0, 0]
  let lastTime = 0
  let decay = 0

  const rectContains = (event: PointerEvent) => {
    const r = target.getBoundingClientRect()
    return (
      event.clientX >= r.left &&
      event.clientX <= r.right &&
      event.clientY >= r.top &&
      event.clientY <= r.bottom
    )
  }

  const point = (event: PointerEvent): [number, number] => {
    const r = target.getBoundingClientRect()
    return [
      Math.max(0, Math.min(1, (event.clientX - r.left) / Math.max(1, r.width))),
      Math.max(
        0,
        Math.min(1, 1 - (event.clientY - r.top) / Math.max(1, r.height))
      ),
    ]
  }

  const clear = () => {
    hovering = false
    lastTime = 0
    decay = 0
    velocity = [0, 0]
  }

  const enter = (event: PointerEvent) => {
    if (!event.isPrimary) return
    hovering = true
    from = to = point(event)
    lastTime = event.timeStamp
    velocity = [0, 0]
  }

  const move = (event: PointerEvent) => {
    if (!event.isPrimary) return
    if (!rectContains(event)) {
      if (hovering || decay > 0) clear()
      return
    }
    hovering = true
    const next = point(event)
    if (lastTime === 0) {
      from = to = next
      lastTime = event.timeStamp
      return
    }
    const dt = Math.max(
      0.004,
      Math.min(0.05, (event.timeStamp - lastTime) / 1000)
    )
    from = to
    to = next
    velocity = [
      Math.max(-2.5, Math.min(2.5, (to[0] - from[0]) / dt)),
      Math.max(-2.5, Math.min(2.5, (to[1] - from[1]) / dt)),
    ]
    lastTime = event.timeStamp
    decay = 8
  }

  const leave = (event: PointerEvent) => {
    if (!event.isPrimary) return
    clear()
  }

  // Window listener only clears stale hover if pointerleave is missed
  // (iframe chrome, portaled menus). It never starts a stir off-card.
  const onGlobalMove = (event: PointerEvent) => {
    if (!event.isPrimary) return
    if ((hovering || decay > 0) && !rectContains(event)) clear()
  }

  target.addEventListener("pointerenter", enter)
  target.addEventListener("pointermove", move)
  target.addEventListener("pointerleave", leave)
  target.addEventListener("pointercancel", leave)
  window.addEventListener("pointermove", onGlobalMove, { passive: true })
  window.addEventListener("blur", clear)

  return {
    get active() {
      return hovering && decay > 0
    },
    get from() {
      return from
    },
    get to() {
      return to
    },
    get velocity() {
      return velocity
    },
    consumeStep() {
      from = to
      if (decay > 0) {
        if (!hovering) {
          velocity = [velocity[0] * 0.45, velocity[1] * 0.45]
        }
        decay--
      }
    },
    dispose() {
      target.removeEventListener("pointerenter", enter)
      target.removeEventListener("pointermove", move)
      target.removeEventListener("pointerleave", leave)
      target.removeEventListener("pointercancel", leave)
      window.removeEventListener("pointermove", onGlobalMove)
      window.removeEventListener("blur", clear)
      clear()
    },
  }
}

import type { Gpu, Target } from "vgpu";
import type { StirInput } from "./pointer-input";
import advectVelocityWgsl from "./advect-velocity.wgsl";
import curlWgsl from "./curl.wgsl";
import vorticityWgsl from "./vorticity.wgsl";
import divergenceWgsl from "./divergence.wgsl";
import pressureWgsl from "./pressure.wgsl";
import projectWgsl from "./project.wgsl";
import advectDyeWgsl from "./advect-dye.wgsl";
import displayWgsl from "./display.wgsl";
import { compute, effect, frame, pingPongStorage, storage } from "vgpu";

const GRID_SIZE = [128, 72] as const;
const DYE_SIZE = [GRID_SIZE[0] * 4, GRID_SIZE[1] * 4] as const;
const CELLS = GRID_SIZE[0] * GRID_SIZE[1];
const DYE_CELLS = DYE_SIZE[0] * DYE_SIZE[1];

export function createFluid(gpu: Gpu) {
  const allocated: object[] = [];
  try {
    const velocity = pingPongStorage(gpu, CELLS * 8);
    allocated.push(velocity.read, velocity.write);
    const dye = pingPongStorage(gpu, DYE_CELLS * 16);
    allocated.push(dye.read, dye.write);
    const pressure = pingPongStorage(gpu, CELLS * 4);
    allocated.push(pressure.read, pressure.write);
    const divergence = storage(gpu, CELLS * 4, "read-write");
    allocated.push(divergence);
    const curl = storage(gpu, CELLS * 4, "read-write");
    allocated.push(curl);
    const passes = createPasses(gpu);
    return {
      gpu,
      velocity,
      dye,
      pressure,
      divergence,
      curl,
      passes,
      step: 0,
    };
  } catch (error) {
    for (const buffer of allocated) {
      destroyBuffer(buffer);
    }
    throw error;
  }
}

export type Fluid = ReturnType<typeof createFluid>;

export function destroyFluid(fluid: Fluid): void {
  const buffers = [
    fluid.velocity.read,
    fluid.velocity.write,
    fluid.dye.read,
    fluid.dye.write,
    fluid.pressure.read,
    fluid.pressure.write,
    fluid.divergence,
    fluid.curl,
  ];
  for (const buffer of buffers) {
    destroyBuffer(buffer);
  }
}

function destroyBuffer(buffer: object) {
  (buffer as { destroy(): void }).destroy();
}

function createPasses(gpu: Gpu) {
  const withGrid = (shader: typeof advectVelocityWgsl) =>
    compute(gpu, shader, {
      set: { grid: { size: GRID_SIZE, dye_size: DYE_SIZE } },
    });
  return {
    advectVelocity: withGrid(advectVelocityWgsl),
    curl: withGrid(curlWgsl),
    vorticity: withGrid(vorticityWgsl),
    divergence: withGrid(divergenceWgsl),
    pressure: withGrid(pressureWgsl),
    project: withGrid(projectWgsl),
    advectDye: withGrid(advectDyeWgsl),
    display: effect(gpu, displayWgsl),
  };
}

export async function prepareFluid(
  fluid: Fluid,
  output: Target
): Promise<void> {
  resizeFluid(fluid, output);
  await fluid.passes.display.compile({ colors: [output.format] });
}

export function resizeFluid(fluid: Fluid, output: Target): void {
  fluid.passes.display.set({ config: { output_size: output.size } });
}

export function stepFluid(fluid: Fluid, input?: StirInput): void {
  const dynamic = inputUniforms(fluid, input);
  const p = fluid.passes;

  p.advectVelocity
    .set({
      input: dynamic,
      src: fluid.velocity.read,
      dst: fluid.velocity.write,
    })
    .dispatch(16, 9);
  fluid.velocity.swap();

  // Confinement restores the small rotating details lost by semi-Lagrangian advection.
  p.curl
    .set({ velocity: fluid.velocity.read, curl: fluid.curl })
    .dispatch(16, 9);
  p.vorticity
    .set({
      src: fluid.velocity.read,
      curl: fluid.curl,
      dst: fluid.velocity.write,
    })
    .dispatch(16, 9);
  fluid.velocity.swap();

  p.divergence
    .set({ velocity: fluid.velocity.read, divergence: fluid.divergence })
    .dispatch(16, 9);
  for (let i = 0; i < 3; i++) {
    p.pressure
      .set({
        params: { decay: i === 0 ? 0.8 : 1 },
        src: fluid.pressure.read,
        divergence: fluid.divergence,
        dst: fluid.pressure.write,
      })
      .dispatch(16, 9);
    fluid.pressure.swap();
  }

  p.project
    .set({
      src: fluid.velocity.read,
      pressure: fluid.pressure.read,
      dst: fluid.velocity.write,
    })
    .dispatch(16, 9);
  fluid.velocity.swap();

  p.advectDye
    .set({
      input: dynamic,
      src: fluid.dye.read,
      velocity: fluid.velocity.read,
      dst: fluid.dye.write,
    })
    .dispatch(64, 36);
  fluid.dye.swap();
  fluid.step++;
  input?.consumeStep();
}

export function renderFluid(fluid: Fluid, output: Target): void {
  fluid.passes.display.set({ dye: fluid.dye.read });
  frame(fluid.gpu, (currentFrame) => {
    currentFrame.pass(output, fluid.passes.display);
  });
}

function inputUniforms(fluid: Fluid, input?: StirInput) {
  const [a, b] = idleEmitters(fluid.step);
  const ramp = Math.min(1, (fluid.step + 1) / 18);
  // Steady idle — duck slightly while stirring so the pointer reads, but never
  // ramp back in a delayed pulse (that looked like the orbs squirting).
  const idle = input?.active ? 0.32 : 0.55;
  const pointerVelocity = input?.velocity ?? ([0, 0] as [number, number]);
  const speed = Math.hypot(...pointerVelocity);
  const direction =
    speed > 1e-4
      ? [pointerVelocity[0] / speed, pointerVelocity[1] / speed]
      : [0, 0];
  const dx = direction[0]!;
  const dy = direction[1]!;
  return {
    step: fluid.step,
    pointer_active: input?.active ? 1 : 0,
    pointer_from: input?.from ?? [0.5, 0.5],
    pointer_to: input?.to ?? [0.5, 0.5],
    pointer_velocity: pointerVelocity,
    pointer_color: [
      0.88 + 0.12 * dx,
      0.38 + 0.28 * dy,
      0.62 - 0.38 * dx,
      1,
    ],
    idle_a: [...a, ramp * idle, 0.0088],
    idle_b: [...b, ramp * idle, 0.0072],
  };
}

function idleEmitters(step: number): [[number, number], [number, number]] {
  const t = step / 60;
  return [
    [0.52 + 0.31 * Math.sin(0.51 * t), 0.46 + 0.19 * Math.sin(0.88 * t + 1.15)],
    [
      0.48 + 0.24 * Math.sin(0.79 * t + 2.3),
      0.54 + 0.26 * Math.sin(0.67 * t + 0.55),
    ],
  ];
}

export struct Grid {
  size: vec2u,
  dye_size: vec2u,
}

export struct Input {
  step: u32,
  pointer_active: f32,
  pointer_from: vec2f,
  pointer_to: vec2f,
  pointer_velocity: vec2f,
  pointer_color: vec4f,
  idle_a: vec4f,
  idle_b: vec4f,
}

export fn index_of(p: vec2i, size: vec2u) -> u32 {
  let q = clamp(p, vec2i(0), vec2i(size) - 1);
  return u32(q.y) * size.x + u32(q.x);
}

export fn cell_uv(p: vec2i, size: vec2u) -> vec2f {
  return (vec2f(p) + 0.5) / vec2f(size);
}

export fn segment_weight(
  p: vec2f,
  a: vec2f,
  b: vec2f,
  radius_squared: f32,
  aspect: f32,
) -> f32 {
  let scale = vec2f(aspect, 1.0);
  let point = p * scale;
  let origin = a * scale;
  let delta = (b - a) * scale;
  let t = clamp(dot(point - origin, delta) / max(dot(delta, delta), 1e-7), 0.0, 1.0);
  let d = point - (origin + t * delta);
  return exp(-dot(d, d) / radius_squared);
}

export fn emitter_weight(p: vec2f, emitter: vec4f, aspect: f32) -> f32 {
  let d = (p - emitter.xy) * vec2f(aspect, 1.0);
  return exp(-dot(d, d) / emitter.w) * emitter.z;
}

import { Grid, Input, index_of, cell_uv, segment_weight, emitter_weight } from "./fluid-common.wgsl";

@group(0) @binding(0) var<uniform> grid: Grid;
@group(0) @binding(1) var<uniform> input: Input;
@group(0) @binding(2) var<storage, read> src: array<vec2f>;
@group(0) @binding(3) var<storage, read_write> dst: array<vec2f>;

fn sample_velocity(p: vec2f) -> vec2f {
  let coord = clamp(p * vec2f(grid.size) - 0.5, vec2f(0), vec2f(grid.size) - 1.0);
  let cell = vec2i(floor(coord));
  let f = fract(coord);
  let bottom = mix(src[index_of(cell, grid.size)], src[index_of(cell + vec2i(1, 0), grid.size)], f.x);
  let top = mix(src[index_of(cell + vec2i(0, 1), grid.size)], src[index_of(cell + vec2i(1, 1), grid.size)], f.x);
  return mix(bottom, top, f.y);
}

@compute @workgroup_size(8, 8)
fn main(@builtin(global_invocation_id) id: vec3u) {
  if (any(id.xy >= grid.size)) { return; }
  let cell = vec2i(id.xy);
  let p = cell_uv(cell, grid.size);
  let aspect = f32(grid.size.x) / f32(grid.size.y);
  let dt = 1.0 / 60.0;
  let source_velocity = src[index_of(cell, grid.size)];
  let backtrace = clamp(p - dt * source_velocity, 0.5 / vec2f(grid.size), 1.0 - 0.5 / vec2f(grid.size));
  var velocity = 0.975 * sample_velocity(backtrace);

  let weight_a = emitter_weight(p, input.idle_a, aspect);
  let weight_b = emitter_weight(p, input.idle_b, aspect);
  let time = f32(input.step) / 60.0;
  let tangent_a = vec2f(0.31 * 0.51 * cos(0.51 * time), 0.19 * 0.88 * cos(0.88 * time + 1.15));
  let tangent_b = vec2f(0.24 * 0.79 * cos(0.79 * time + 2.3), 0.26 * 0.67 * cos(0.67 * time + 0.55));
  velocity += dt * (weight_a * (2.2 * tangent_a + 1.6 * vec2f(-tangent_a.y, tangent_a.x))
                  + weight_b * (2.2 * tangent_b - 1.6 * vec2f(-tangent_b.y, tangent_b.x)));

  if (input.pointer_active > 0.0) {
    let weight = segment_weight(p, input.pointer_from, input.pointer_to, 0.0032, aspect);
    velocity += weight * input.pointer_velocity * 0.7;
  }

  let speed = length(velocity);
  if (speed > 2.5) { velocity *= 2.5 / speed; }
  dst[index_of(cell, grid.size)] = velocity;
}

